def _polynomial(x, degree):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, j], axis=1) for k in range(1, degree + 1) for j in combinations_with_replacement(range(x.shape[1]), k)])

def _dictionary(z, f, c1, c2):
    from itertools import combinations
    out = [_polynomial(w, 4) for w in (z, f)]
    for w in (z, f, c1, c2):
        (a, b) = np.triu_indices(w.shape[1], 1)
        pairs = np.column_stack((w, w[:, a] + w[:, b], w[:, a] - w[:, b]))
        out.extend((np.sin(1.5 * pairs), np.cos(1.5 * pairs), np.tanh(1.5 * pairs), pairs / (1 + pairs * pairs), np.log1p(pairs * pairs)))
        out.append(np.column_stack([w[:, i] * w[:, j] * w[:, k] for (i, j, k) in combinations(range(w.shape[1]), 3)]))
    for w in (f, c1, c2):
        out.append((z[:, :, None] * w[:, None, :]).reshape(len(z), -1))
        out.append((z[:, :, None] ** 2 * w[:, None, :]).reshape(len(z), -1))
    return np.column_stack(out)

def basis(z, k):
    from itertools import combinations_with_replacement
    return np.column_stack([np.ones(len(z)), z] + [np.prod(z[:, j], axis=1) for d in range(2, k + 1) for j in combinations_with_replacement(range(4), d)])

def act(h, f):
    if f == 'sin':
        return np.sin(h)
    if f == 'tanh':
        return np.tanh(h)
    if f == 'rat':
        return h / (1 + h * h)
    if f == 'soft':
        return h / np.sqrt(1 + h * h)
    if f == 'atan':
        return np.arctan(h)
    if f == 'exp':
        return np.exp(-h * h / 2)
